// Title: C# Unit Test: Verify Aspose.Cells HTML Export Includes Comment Icons (IsExportComments = true)
// Description: Creates a workbook, adds a visible comment to cell A1, saves it as HTML with HtmlSaveOptions.IsExportComments enabled, reads the generated file, and asserts that the markup contains the comment‑icon identifier, then cleans up the temporary file.
// Keywords: Aspose.Cells | HTML export | comment icons | IsExportComments | C# unit test | MSTest | xUnit | NUnit | regression testing | CI pipeline
// Common Searches: Aspose.Cells unit test for HTML comment export | verify IsExportComments adds comment markup | C# test Aspose.Cells HTML export comments | check comment icon in generated HTML Aspose | automated test for Aspose.Cells HTML comments
// Developer Intent: Write a unit test that confirms comment icons are present in the HTML output when IsExportComments is set to true.
// Use Cases: Ensure Excel comments are retained as icons in HTML reports generated by Aspose.Cells. | Add regression checks for HTML export settings in automated test suites. | Validate comment visibility in CI/CD pipelines for spreadsheet‑to‑HTML conversion.
// AI Prompts: Generate an MSTest method in C# that creates a workbook with a visible comment, exports it to HTML with IsExportComments enabled, reads the file, and fails if the comment icon markup is missing. | Write an xUnit test that adds a comment to cell A1, saves the workbook as HTML using Aspose.Cells with comment export turned on, and asserts the output contains the word "comment". | Provide a NUnit example that verifies Aspose.Cells HtmlSaveOptions.IsExportComments correctly includes comment icons in the generated HTML file.

using System;
using System.IO;
using Aspose.Cells;

namespace AsposeCellsExamples
{
    // Creates a workbook, adds a visible comment to cell A1, saves it as HTML with HtmlSaveOptions.IsExportComments enabled, reads the generated file, and asserts that the markup contains the comment‑icon identifier, then cleans up the temporary file.
    public class HtmlExportCommentsDemo
    {
        public static void Main()
        {
            // Create a workbook and add a comment to cell A1
            var workbook = new Workbook();
            var sheet = workbook.Worksheets[0];
            int commentIndex = sheet.Comments.Add("A1");
            var comment = sheet.Comments[commentIndex];
            comment.Note = "This is a test comment";
            comment.IsVisible = true; // ensure the comment is visible

            // Configure HTML save options to export comments
            var htmlOptions = new HtmlSaveOptions
            {
                IsExportComments = true
            };

            // Save to a temporary HTML file
            string tempHtmlPath = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString() + ".html");
            try
            {
                workbook.Save(tempHtmlPath, htmlOptions);

                // Verify that the file was created
                if (!File.Exists(tempHtmlPath))
                    throw new FileNotFoundException("The HTML file was not created.", tempHtmlPath);

                // Read the generated HTML
                string htmlContent = File.ReadAllText(tempHtmlPath);

                // Verify that the HTML contains comment icon markup (Aspose uses the word "comment" in the output)
                if (htmlContent.IndexOf("comment", StringComparison.OrdinalIgnoreCase) < 0)
                {
                    throw new InvalidOperationException("The exported HTML does not contain comment icons despite IsExportComments being true.");
                }

                Console.WriteLine("HTML export with comments succeeded.");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"An error occurred: {ex.Message}");
            }
            finally
            {
                // Clean up the temporary file
                if (File.Exists(tempHtmlPath))
                {
                    try
                    {
                        File.Delete(tempHtmlPath);
                    }
                    catch (Exception deleteEx)
                    {
                        Console.WriteLine($"Failed to delete temporary file: {deleteEx.Message}");
                    }
                }
            }
        }
    }
}
